    "text": "{\n    \"name\": \"microturtle\",\n    \"version\": \"0.0.9\",\n    \"dependencies\": {\n        \"core\": \"*\"\n    },\n    \"description\": \"A LOGO-like turtle library\",\n    \"files\": [\n        \"turtle.ts\",\n        \"README.md\"\n    ],\n    \"testFiles\": [\n        \"tests.ts\"\n    ],\n    \"public\": true\n}",
    "blob": "9ab7fe0a7892572644ff133c37e1ce7b80581658"
