    "text": "{\n    \"name\": \"pxt-kitronik-motor-driver\",\n    \"version\": \"0.0.3\",\n    \"description\": \"Blocks to simplify using Kitronik products in PXT\",\n    \"license\": \"MIT\",\n    \"dependencies\": {\n        \"core\": \"*\"\n    },\n    \"files\": [\n        \"README.md\",\n        \"ns.ts\",\n        \"motors.ts\"\n    ],\n    \"testFiles\": [\n        \"tests.ts\"\n    ],\n    \"public\": true\n}",
